function t(n){if(n==null||n==="")return 0;let r=typeof n=="string"?Number(n):n;return Number.isFinite(r)?r:0}function i(n){return new Intl.NumberFormat("es-MX",{minimumFractionDigits:2,maximumFractionDigits:4}).format(t(n))}function e(n,r="MXN"){return new Intl.NumberFormat("es-MX",{style:"currency",currency:r,minimumFractionDigits:2,maximumFractionDigits:4}).format(t(n))}export{i as a,e as b};
